import skillsJson from '../data/skills.json' with { type: 'json' };
import { ITEM_SKILLS, type ItemSkill } from './items.js';

/**
 * Skill XP (docs/design/holding.md, GAME DESIGN's curve). A skill has no level
 * cap. The XP to go from level L to L + 1 is `xpToNext(L)`; data/skills.json
 * (generated by tools/skills-table.mjs, never computed at runtime) holds the
 * cumulative XP each level needs, from 1 to `SKILL_TABLE_LEVELS`; beyond the
 * table the same formula runs here. XP is not an item: the server keeps it in
 * its own table, written only when an action settles.
 */

/** The skills of M2: Woodcutting, Mining, Farming (Farming has no station until Task 5). */
export const SKILLS: readonly ItemSkill[] = ITEM_SKILLS;
export type Skill = ItemSkill;

export function isSkill(value: unknown): value is Skill {
  return typeof value === 'string' && (SKILLS as readonly string[]).includes(value);
}

/** The XP to go from level `level` to `level + 1`: round(40 + 12,300 × (1.08^level − 1.08)); level 2 is at 40. */
export function xpToNext(level: number): number {
  return Math.round(40 + 12300 * (Math.pow(1.08, level) - 1.08));
}

/** How many levels the generated table covers. */
export const SKILL_TABLE_LEVELS = 200;

function loadTable(): readonly number[] {
  const levels: unknown = skillsJson.levels;
  if (
    !Array.isArray(levels) ||
    levels.length !== SKILL_TABLE_LEVELS ||
    !levels.every((v, i) => Number.isSafeInteger(v) && (i === 0 ? v === 0 : v > (levels[i - 1] as number)))
  )
    throw new Error(`data/skills.json: levels must be ${SKILL_TABLE_LEVELS} rising safe integers from 0`);
  return levels as number[];
}

/** `skillTable[L - 1]` is the cumulative XP level L needs (level 1 at 0, level 2 at 40). */
export const skillTable: readonly number[] = loadTable();

/** The cumulative XP level `level` needs: the table, or the formula summed past it. */
export function xpForLevel(level: number): number {
  if (level <= 1) return 0;
  if (level <= SKILL_TABLE_LEVELS) return skillTable[level - 1] ?? 0;
  let xp = skillTable[SKILL_TABLE_LEVELS - 1] ?? 0;
  for (let l = SKILL_TABLE_LEVELS; l < level; l++) xp += xpToNext(l);
  return xp;
}

/** A skill's state at `xp` total: its level, the XP into that level and the XP still to go to the next. */
export interface SkillProgress {
  xp: number;
  level: number;
  into: number;
  toNext: number;
}

/** The level `xp` total reaches (no cap), with the XP into it and to the next. */
export function skillProgress(xp: number): SkillProgress {
  const total = Math.max(0, Math.floor(xp));
  // The table: the last level whose cumulative XP is at or under the total.
  let lo = 1;
  let hi = SKILL_TABLE_LEVELS;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if ((skillTable[mid - 1] ?? 0) <= total) lo = mid;
    else hi = mid - 1;
  }
  let level = lo;
  let base = skillTable[level - 1] ?? 0;
  // Past the table: the same formula, one level at a time.
  while (level >= SKILL_TABLE_LEVELS && base + xpToNext(level) <= total) {
    base += xpToNext(level);
    level++;
  }
  return { xp: total, level, into: total - base, toNext: base + xpToNext(level) - total };
}

/** The level `xp` total reaches. */
export function levelFromXp(xp: number): number {
  return skillProgress(xp).level;
}
